  bool: t.procedure.input(z.boolean()).use(o => o.next()).query(o => o.input),
  literal: t.procedure.input(z.literal('ok')).use(o => o.next()).query(o => o.input),
  mixed: t.procedure.input(z.union([z.string(), z.number()])).use(o => o.next()).query(o => o.input),
  nullable: t.procedure.input(z.string().nullable()).use(o => o.next()).query(o => o.input),
  optional: t.procedure.input(z.string().optional()).use(o => o.next()).query(o => o.input),
  noInput: t.procedure.use(o => o.next()).query(o => o.input),
});
type Inputs = inferRouterInputs<typeof router>;
type Outputs = inferRouterOutputs<typeof router>;
type Checks = [
  Assert<Equal<Inputs['str'], string>>, Assert<Equal<Outputs['str'], string>>,
  Assert<Equal<Inputs['num'], number>>, Assert<Equal<Outputs['num'], number>>,
  Assert<Equal<Inputs['bool'], boolean>>, Assert<Equal<Outputs['bool'], boolean>>,
  Assert<Equal<Inputs['literal'], 'ok'>>, Assert<Equal<Outputs['literal'], 'ok'>>,
  Assert<Equal<Inputs['mixed'], string | number>>, Assert<Equal<Outputs['mixed'], string | number>>,
  Assert<Equal<Inputs['nullable'], string | null>>, Assert<Equal<Outputs['nullable'], string | null>>,
  Assert<Equal<Inputs['optional'], string | undefined>>, Assert<Equal<Outputs['optional'], string | undefined>>,
  Assert<Equal<Inputs['noInput'], void>>, Assert<Equal<Outputs['noInput'], undefined>>
];
